#include<iostream>
#include<string>
using namespace std;
class Student{
private:
 string id,name; double score;
public:
 Student(string i,string n,double s):id(i),name(n),score(s){}
 void showInfo(){ cout<<id<<' '<<name<<' '<<score<<endl; }
};
int main(){
 Student s("2026001","ZhangSan",90.5);
 s.showInfo();
 return 0;
}

#include<iostream>
using namespace std;
class Shape{
public:
 virtual double getArea()=0;
 virtual ~Shape(){}
};
class Circle: public Shape{
 double r;
public:
 Circle(double rr):r(rr){}
 double getArea(){ return 3.14*r*r; }
};
class Rectangle: public Shape{
 double w,h;
public:
 Rectangle(double ww,double hh):w(ww),h(hh){}
 double getArea(){ return w*h; }
};
int main(){
 Shape *p1=new Circle(2);
 Shape *p2=new Rectangle(3,4);
 cout<<p1->getArea()<<endl;
 cout<<p2->getArea()<<endl;
 delete p1;
 delete p2;
 return 0;
}
